function ridgeCount(heights) {
    let count = 0;
    for (let i = 0; i < heights.length; i++) {
        let ridge = true;
        for (let j = 0; j < i; j++)
            if (heights[j] >= heights[i])
                ridge = false;
        if (ridge)
            count++;
    }
    return count;
}

function ridgeCount(heights) {
    let count = 0;
    let highest = -Infinity;
    for (const height of heights) {
        if (height > highest) {
            count++;
            highest = height;
        }
    }
    return count;
}
